1	import type { AttributionForNightOutput } from "@kip/shared/attribution";
2	import { SAY_SIMULATED } from "@kip/shared/domain";
3	
4	/** `forNight` draws this many random windows. The sentence reduces that count. */
5	export const RANDOM_WINDOW_DRAWS = 1000;
6	
7	export const TITLE = "Wake-ups";
8	export const METHOD =
9	  "Wake-ups linked to noise spikes, counted against random moments from the same night.";
10	export const TRACK_CAPTION = "Wake-ups. A filled mark followed a spike.";
11	export const NO_WAKE_UPS = "No wake-ups recorded for this night.";
12	export const LOADING = "Loading wake-ups.";
13	export const LOAD_ERROR = "We could not load wake-ups for this night.";
14	export const TRY_AGAIN = "Try again";
15	
16	function capitalise(phrase: string): string {
17	  return phrase.charAt(0).toUpperCase() + phrase.slice(1);
18	}
19	
20	export const SIMULATED_NIGHT = `${capitalise(SAY_SIMULATED)} night.`;
21	
22	/** 24-hour Europe/London time, matching the night timeline. */
23	export function clock(epochSeconds: number): string {
24	  return new Intl.DateTimeFormat("en-GB", {
25	    timeZone: "Europe/London",
26	    hour: "2-digit",
27	    minute: "2-digit",
28	    hourCycle: "h23",
29	  }).format(new Date(epochSeconds * 1000));
30	}
31	
32	function gcd(a: number, b: number): number {
33	  let x = Math.abs(a);
34	  let y = Math.abs(b);
35	  while (y !== 0) {
36	    const next = x % y;
37	    x = y;
38	    y = next;
39	  }
40	  return x || 1;
41	}
42	
43	/**
44	 * The random-window rate as a reduced count. 0.1 is 100 of 1000, shown as 1 of 10.
45	 * A rate of 0 stays 0 of 1000, the number of draws.
46	 */
47	export function randomMomentCounts(rate: number): { hits: number; moments: number } {
48	  if (!Number.isFinite(rate) || rate <= 0) return { hits: 0, moments: RANDOM_WINDOW_DRAWS };
49	  const hits = Math.round(Math.min(1, rate) * RANDOM_WINDOW_DRAWS);
50	  if (hits <= 0) return { hits: 0, moments: RANDOM_WINDOW_DRAWS };
51	  const divisor = gcd(hits, RANDOM_WINDOW_DRAWS);
52	  return { hits: hits / divisor, moments: RANDOM_WINDOW_DRAWS / divisor };
53	}
54	
55	/**
56	 * Counts for this night, then the random-moment comparison.
57	 * Wording comes from `night.text` ("followed", never "caused by").
58	 */
59	export function attributionSummaryText(
60	  result: Pick<AttributionForNightOutput, "night" | "randomWindowRate">,
61	): string {
62	  const random = randomMomentCounts(result.randomWindowRate);
63	  return `${result.night.text}; random moments: ${random.hits} of ${random.moments}`;
64	}
65	
66	export function wakeLine(wake: { t: number; linkedEventId: string | null }): string {
67	  const when = clock(wake.t);
68	  if (wake.linkedEventId) return `${when} Wake-up, followed a spike`;
69	  return `${when} Wake-up`;
70	}
71	
72	export function spikeLine(epochSeconds: number): string {
73	  return `Spike at ${clock(epochSeconds)}`;
74	}
