1	import type { AttributionForNightOutput } from "@kip/shared/attribution";
2	
3	export type WakeMark = {
4	  t: number;
5	  source: AttributionForNightOutput["wakeUps"][number]["source"];
6	  linkedEventId: string | null;
7	};
8	
9	export type SpikeMark = {
10	  id: string;
11	  t: number;
12	};
13	
14	export type AttributionMarks = {
15	  wakeUps: WakeMark[];
16	  /** Spikes a wake-up followed. A spike that only shares a timestamp is not included. */
17	  spikes: SpikeMark[];
18	};
19	
20	/**
21	 * Marks for the night timeline. `linkedEventId` comes from `attribution.forNight`.
22	 * Hand-placed links on a night timeline are not an input.
23	 */
24	export function marksFromAttribution(
25	  result: Pick<AttributionForNightOutput, "wakeUps">,
26	  events: readonly { id: string; t: number }[],
27	): AttributionMarks {
28	  const byId = new Map(events.map((event) => [event.id, event]));
29	  const spikes: SpikeMark[] = [];
30	  const seen = new Set<string>();
31	  const wakeUps = result.wakeUps.map((wake) => ({
32	    t: wake.t,
33	    source: wake.source,
34	    linkedEventId: wake.linkedEventId,
35	  }));
36	  wakeUps.sort((a, b) => a.t - b.t || sourceRank(a.source) - sourceRank(b.source));
37	
38	  for (const wake of wakeUps) {
39	    const id = wake.linkedEventId;
40	    if (!id || seen.has(id)) continue;
41	    const event = byId.get(id);
42	    if (!event || !Number.isFinite(event.t)) continue;
43	    seen.add(id);
44	    spikes.push({ id, t: event.t });
45	  }
46	
47	  return { wakeUps, spikes };
48	}
49	
50	/** 0 at `start`, 1 at `end`, clamped. */
51	export function fractionAlong(t: number, start: number, end: number): number {
52	  if (!Number.isFinite(t) || !Number.isFinite(start) || !Number.isFinite(end) || end <= start) {
53	    return 0;
54	  }
55	  return Math.min(1, Math.max(0, (t - start) / (end - start)));
56	}
57	
58	export function epochSeconds(iso: string): number {
59	  return Date.parse(iso) / 1000;
60	}
61	
62	function sourceRank(source: WakeMark["source"]): number {
63	  return source === "stage" ? 0 : 1;
64	}
