1	import type { AttributionForNightOutput } from "@kip/shared/attribution";
2	import { useState } from "react";
3	import { type LayoutChangeEvent, StyleSheet, View } from "react-native";
4	import { radius, space, Text, useColors } from "@/lib/ui";
5	import { clock, NO_WAKE_UPS, spikeLine, TRACK_CAPTION, wakeLine } from "../copy";
6	import { epochSeconds, fractionAlong, marksFromAttribution } from "../marks";
7	
8	const MARK = 12;
9	
10	/**
11	 * Wake-ups from `attribution.forNight`, and the spikes those wake-ups followed.
12	 * A filled diamond followed a spike. A square is that spike. Hollow diamonds did not.
13	 */
14	export function WakeMarkers({
15	  startedAt,
16	  endedAt,
17	  result,
18	  events,
19	}: {
20	  startedAt: string;
21	  endedAt: string;
22	  result: Pick<AttributionForNightOutput, "wakeUps">;
23	  events: readonly { id: string; t: number }[];
24	}) {
25	  const colors = useColors();
26	  const [width, setWidth] = useState(0);
27	  const onLayout = (event: LayoutChangeEvent) => {
28	    setWidth(Math.round(event.nativeEvent.layout.width));
29	  };
30	  const marks = marksFromAttribution(result, events);
31	  const start = epochSeconds(startedAt);
32	  const end = epochSeconds(endedAt);
33	  const x = (t: number) => fractionAlong(t, start, end) * width;
34	  const spikeById = new Map(marks.spikes.map((spike) => [spike.id, spike]));
35	
36	  return (
37	    <View style={styles.block}>
38	      <Text variant="caption">{TRACK_CAPTION}</Text>
39	      <View
40	        accessibilityLabel={`${marks.wakeUps.length} wake-ups`}
41	        onLayout={onLayout}
42	        style={[styles.track, { backgroundColor: colors.background, borderColor: colors.border }]}
43	      >
44	        {width > 0 &&
45	          marks.wakeUps.map((wake) => {
46	            const spike = wake.linkedEventId ? spikeById.get(wake.linkedEventId) : undefined;
47	            if (!spike) return null;
48	            const from = x(spike.t);
49	            const to = x(wake.t);
50	            const left = Math.min(from, to);
51	            const lineWidth = Math.abs(to - from);
52	            if (lineWidth <= 0) return null;
53	            return (
54	              <View
55	                key={`${wake.t}-${wake.source}-link`}
56	                style={[styles.link, { left, width: lineWidth, backgroundColor: colors.accent }]}
57	              />
58	            );
59	          })}
60	        {width > 0 &&
61	          marks.spikes.map((spike) => (
62	            <View
63	              key={spike.id}
64	              style={[
65	                styles.spike,
66	                {
67	                  left: x(spike.t) - 4,
68	                  backgroundColor: colors.accent,
69	                  borderColor: colors.accent,
70	                },
71	              ]}
72	            />
73	          ))}
74	        {width > 0 &&
75	          marks.wakeUps.map((wake) => {
76	            const linked = wake.linkedEventId !== null;
77	            return (
78	              <View
79	                key={`${wake.t}-${wake.source}`}
80	                style={[
81	                  styles.wake,
82	                  {
83	                    left: x(wake.t) - MARK / 2,
84	                    borderColor: linked ? colors.accent : colors.textSecondary,
85	                    backgroundColor: linked ? colors.accent : colors.background,
86	                  },
87	                ]}
88	              />
89	            );
90	          })}
91	      </View>
92	      <View style={styles.axis}>
93	        <Text variant="caption">{clock(start)}</Text>
94	        <Text variant="caption">{clock(end)}</Text>
95	      </View>
96	      {marks.wakeUps.length === 0 ? <Text>{NO_WAKE_UPS}</Text> : null}
97	      <View style={styles.list}>
98	        {marks.wakeUps.map((wake) => {
99	          const spike = wake.linkedEventId ? spikeById.get(wake.linkedEventId) : undefined;
100	          return (
101	            <View key={`${wake.t}-${wake.source}`} style={styles.item}>
102	              <Text>{wakeLine(wake)}</Text>
103	              {spike ? <Text variant="caption">{spikeLine(spike.t)}</Text> : null}
104	            </View>
105	          );
106	        })}
107	      </View>
108	    </View>
109	  );
110	}
111	
112	const styles = StyleSheet.create({
113	  block: { gap: space.sm },
114	  track: { height: 32, borderWidth: 1, borderRadius: radius.sm },
115	  axis: { flexDirection: "row", justifyContent: "space-between" },
116	  link: { position: "absolute", top: 16, height: 1 },
117	  spike: {
118	    position: "absolute",
119	    top: 12,
120	    width: 8,
121	    height: 8,
122	    borderWidth: 1,
123	  },
124	  wake: {
125	    position: "absolute",
126	    top: 10,
127	    width: MARK,
128	    height: MARK,
129	    borderWidth: 2,
130	    transform: [{ rotate: "45deg" }],
131	  },
132	  list: { gap: space.sm },
133	  item: { gap: space.xs },
134	});
