1	import type { AttributionForNightOutput } from "@kip/shared/attribution";
2	import { useQuery } from "@tanstack/react-query";
3	import { useTRPC } from "@/lib/trpc";
4	import { Button, Card, Screen, Text } from "@/lib/ui";
5	import { AttributionSummary, WakeMarkers } from "../components";
6	import { LOAD_ERROR, LOADING, METHOD, SIMULATED_NIGHT, TITLE, TRY_AGAIN } from "../copy";
7	import { DEMO_NIGHT_ID, demoAttribution, demoEvents, demoWindow } from "../data/demo";
8	
9	type Ready = {
10	  kind: "ready";
11	  result: AttributionForNightOutput;
12	  startedAt: string;
13	  endedAt: string;
14	  events: readonly { id: string; t: number }[];
15	  simulated: boolean;
16	};
17	
18	type State = { kind: "loading" } | { kind: "error"; retry: () => void } | Ready;
19	
20	const isStub = (error: unknown) =>
21	  (error as { data?: { code?: string } } | null)?.data?.code === "NOT_IMPLEMENTED";
22	
23	/**
24	 * Latest night's `attribution.forNight` result. Marks never come from the
25	 * timeline document's hand-placed wake-ups. A missing API shows the captured
26	 * result for the shared night upload, labelled simulated.
27	 */
28	function useAttributionNight(): State {
29	  const trpc = useTRPC();
30	  const list = useQuery({ ...trpc.night.list.queryOptions(), retry: false });
31	  const latest = list.data
32	    ?.slice()
33	    .sort((a, b) => b.startedAt.localeCompare(a.startedAt))[0]?.nightId;
34	  const night = useQuery({
35	    ...trpc.night.get.queryOptions({ nightId: latest ?? DEMO_NIGHT_ID }),
36	    enabled: latest !== undefined,
37	    retry: false,
38	  });
39	  const attributed = useQuery({
40	    ...trpc.attribution.forNight.queryOptions({ nightId: latest ?? DEMO_NIGHT_ID }),
41	    enabled: latest !== undefined,
42	    retry: false,
43	  });
44	
45	  if (list.isPending || (latest !== undefined && (night.isPending || attributed.isPending))) {
46	    return { kind: "loading" };
47	  }
48	  if (latest !== undefined) {
49	    if (night.data && attributed.data) {
50	      return {
51	        kind: "ready",
52	        simulated: false,
53	        result: attributed.data,
54	        startedAt: night.data.startedAt,
55	        endedAt: night.data.endedAt,
56	        events: night.data.events.map((event) => ({ id: event.id, t: event.t })),
57	      };
58	    }
59	    return {
60	      kind: "error",
61	      retry: () => {
62	        void night.refetch();
63	        void attributed.refetch();
64	      },
65	    };
66	  }
67	  if (list.isError && !isStub(list.error)) {
68	    return { kind: "error", retry: () => void list.refetch() };
69	  }
70	  return {
71	    kind: "ready",
72	    simulated: true,
73	    result: demoAttribution,
74	    startedAt: demoWindow.startedAt,
75	    endedAt: demoWindow.endedAt,
76	    events: demoEvents,
77	  };
78	}
79	
80	// Not routed yet. The night tab still draws its own timeline wake-ups.
81	export function AttributionScreen() {
82	  const state = useAttributionNight();
83	  return (
84	    <Screen>
85	      <Text variant="title">{TITLE}</Text>
86	      <Text variant="caption">{METHOD}</Text>
87	      {state.kind === "loading" && <Text variant="caption">{LOADING}</Text>}
88	      {state.kind === "error" && (
89	        <Card>
90	          <Text>{LOAD_ERROR}</Text>
91	          <Button label={TRY_AGAIN} onPress={state.retry} />
92	        </Card>
93	      )}
94	      {state.kind === "ready" && (
95	        <>
96	          {state.simulated ? <Text variant="caption">{SIMULATED_NIGHT}</Text> : null}
97	          <Card>
98	            <AttributionSummary result={state.result} />
99	            <WakeMarkers
100	              startedAt={state.startedAt}
101	              endedAt={state.endedAt}
102	              result={state.result}
103	              events={state.events}
104	            />
105	          </Card>
106	        </>
107	      )}
108	    </Screen>
109	  );
110	}
