1	import { describe, expect, test } from "bun:test";
2	import { toAttributionView } from "@kip/shared/attribution";
3	import { bannedWording, detectWakeUps, linkWakeUps } from "@kip/shared/domain";
4	import { nightTimeline, nightUpload } from "@kip/shared/night";
5	import nightTimelineFixture from "../../../../../packages/shared/src/night/fixtures/night-timeline.json";
6	import nightUploadFixture from "../../../../../packages/shared/src/night/fixtures/night-upload.json";
7	import {
8	  attributionSummaryText,
9	  clock,
10	  LOAD_ERROR,
11	  LOADING,
12	  METHOD,
13	  NO_WAKE_UPS,
14	  SIMULATED_NIGHT,
