24	/** Same FNV-1a mix as the server's `attributionSeed`, so the baseline matches forNight. */
25	function attributionSeed(nightId: string): number {
26	  let hash = 0x811c9dc5;
27	  for (let i = 0; i < nightId.length; i++) {
28	    hash ^= nightId.charCodeAt(i);
29	    hash = Math.imul(hash, 0x01000193);
30	  }
31	  return hash | 0;
32	}
