34	const timeline = nightTimeline.parse(nightTimelineFixture);
35	const upload = nightUpload.parse(nightUploadFixture);
36	
37	function sentences(): string[] {
38	  const summary = attributionSummaryText(demoAttribution);
39	  const marks = marksFromAttribution(demoAttribution, demoEvents);
40	  const example = attributionSummaryText({
41	    night: toAttributionView([{ wakeUps: 4, followedSpike: 3 }]),
42	    randomWindowRate: 0.1,
43	  });
44	  const linked = attributionSummaryText({
45	    night: toAttributionView([{ wakeUps: 1, followedSpike: 1 }]),
46	    randomWindowRate: 0,
47	  });
