51	    TRACK_CAPTION,
52	    NO_WAKE_UPS,
53	    LOADING,
54	    LOAD_ERROR,
55	    TRY_AGAIN,
56	    SIMULATED_NIGHT,
57	    summary,
58	    example,
59	    linked,
60	    ...marks.wakeUps.map((wake) => wakeLine(wake)),
61	    clock(Date.parse(demoWindow.startedAt) / 1000),
