76	  test("a single wake-up stays singular, and a zero rate is 0 of 1000", () => {
77	    expect(
78	      attributionSummaryText({
79	        night: toAttributionView([{ wakeUps: 1, followedSpike: 1 }]),
80	        randomWindowRate: 0,
81	      }),
