83	  });
84	
85	  test("the random-window rate reduces, and a rate above 1 clamps", () => {
86	    const night = toAttributionView([{ wakeUps: 2, followedSpike: 0 }]);
87	    expect(attributionSummaryText({ night, randomWindowRate: 0.14 })).toBe(
88	      "0 of 2 wake-ups followed a spike; random moments: 7 of 50",
