109	describe("marks from forNight", () => {
110	  test("the shared upload is 0 of 2, and co-timed spikes are not links", () => {
111	    const sleep = upload.sleep;
112	    if (!sleep) throw new Error("night upload has no sleep");
113	    const start = Date.parse(upload.startedAt) / 1000;
114	    const end = Date.parse(upload.endedAt) / 1000;
