144	    expect(marks.wakeUps).toHaveLength(2);
145	    expect(marks.spikes).toHaveLength(0);
146	    expect(marks.wakeUps.every((wake) => wake.linkedEventId === null)).toBe(true);
147	    expect(marks.wakeUps.map((wake) => wakeLine(wake))).toEqual(["01:17 Wake-up", "06:41 Wake-up"]);
