157	  });
158	
159	  test("a linked spike is marked only through linkedEventId", () => {
160	    const night = toAttributionView([{ wakeUps: 4, followedSpike: 3 }]);
161	    const start = Date.parse("2026-11-13T23:00:00Z") / 1000;
162	    const result = {
163	      wakeUps: [
164	        { t: start + 16 * 60, source: "stage" as const, linkedEventId: "a" },
165	        { t: start + 33 * 60, source: "heartRate" as const, linkedEventId: "b" },
166	        { t: start + 50 * 60, source: "stage" as const, linkedEventId: "c" },
167	        { t: start + 66 * 60, source: "stage" as const, linkedEventId: null },
