171	      { id: "a", t: start + 15 * 60 },
172	      { id: "b", t: start + 32 * 60 },
173	      { id: "c", t: start + 49 * 60 },
174	      { id: "same-time", t: start + 66 * 60 },
175	    ];
176	    const marks = marksFromAttribution(result, events);
177	    expect(marks.spikes.map((spike) => spike.id)).toEqual(["a", "b", "c"]);
178	    expect(marks.wakeUps.map((wake) => wakeLine(wake))).toEqual([
179	      "23:16 Wake-up, followed a spike",
180	      "23:33 Wake-up, followed a spike",
181	      "23:50 Wake-up, followed a spike",
182	      "00:06 Wake-up",
183	    ]);
