90	  const found: string[] = [];
91	  for (const rule of WORDING_RULES) {
92	    if (topic && rule.topic !== topic) continue;
93	    if (rule.topic === "phone") {
94	      const bare = text.replace(/relative dB/gi, "");
95	      if (/\bdB\b/i.test(bare)) found.push(NEVER_BARE_DB);
