60	/**
61	 * Wake-ups during a sleep session (docs/DOMAIN.md, "Wake-up attribution").
62	 * An awake stage counts when it begins in the session at or after sleep onset
63	 * (the first core, deep or rem). The awake stretch before falling asleep does not.
64	 * A heart-rate jump is a rise of `HEART_RATE_JUMP_BPM` within
65	 * `HEART_RATE_JUMP_MAX_GAP_SECONDS`, one wake-up per run of rises. When `stages`
66	 * is passed, jumps count only during core, deep or rem. When it is omitted, jumps
67	 * anywhere in the session count.
68	 */
69	export function detectWakeUps(input: {
70	  sessionStart: number;
71	  sessionEnd: number;
72	  stages?: readonly StageInterval[];
73	  /** [epoch seconds, beats per minute] */
74	  heartRate?: readonly (readonly [number, number])[];
75	}): WakeUp[] {
76	  const { sessionStart, sessionEnd } = input;
77	  if (
78	    !Number.isFinite(sessionStart) ||
79	    !Number.isFinite(sessionEnd) ||
80	    sessionEnd <= sessionStart
81	  ) {
82	    return [];
83	  }
84	
85	  const found: WakeUp[] = [];
86	  const stages = input.stages;
87	  if (stages) {
88	    const onset = sleepOnset(stages, sessionStart, sessionEnd);
89	    if (onset !== null) {
90	      for (const stage of stages) {
91	        if (stage.stage !== "awake") continue;
92	        if (!Number.isFinite(stage.start) || !Number.isFinite(stage.end)) continue;
93	        if (stage.end <= stage.start) continue;
94	        if (stage.start < sessionStart || stage.start >= sessionEnd) continue;
95	        if (stage.start < onset) continue;
96	        found.push({ t: stage.start, source: "stage" });
97	      }
98	    }
99	  }
100	
101	  const heart = heartSamples(input.heartRate, sessionStart, sessionEnd);
102	  let rising = false;
103	  for (let i = 1; i < heart.length; i++) {
104	    const prev = heart[i - 1];
105	    const curr = heart[i];
106	    if (!prev || !curr) continue;
107	    const sudden =
108	      curr.t - prev.t <= HEART_RATE_JUMP_MAX_GAP_SECONDS &&
109	      curr.bpm - prev.bpm >= HEART_RATE_JUMP_BPM;
110	    if (!sudden) {
111	      rising = false;
112	      continue;
113	    }
114	    if (!rising && (!stages || asleepAt(stages, curr.t))) {
115	      found.push({ t: curr.t, source: "heartRate" });
116	    }
117	    rising = true;
118	  }
119	
120	  found.sort((a, b) => a.t - b.t || sourceRank(a.source) - sourceRank(b.source));
121	  return found;
122	}
