124	/**
125	 * Counts wake-ups that a spike preceded by 60 to 120 seconds, and the share of
126	 * random windows of that same length (seeded) that contain a spike.
127	 * The same night and seed always return the same baseline rate.
128	 */
129	export function linkWakeUps(input: {
130	  spikes: readonly { t: number }[];
131	  wakeUps: readonly { t: number }[];
132	  /** Epoch seconds */
133	  nightStart: number;
134	  nightEnd: number;
135	  seed: number;
136	}): WakeUpLink {
137	  const times = input.spikes.map((spike) => spike.t).filter((t) => Number.isFinite(t));
138	  times.sort((a, b) => a - b);
139	
140	  let wakeUps = 0;
141	  let followedSpike = 0;
142	  for (const wake of input.wakeUps) {
143	    if (!Number.isFinite(wake.t)) continue;
144	    wakeUps += 1;
145	    const start = wake.t - ATTRIBUTION_WINDOW_SECONDS.max;
146	    const end = wake.t - ATTRIBUTION_WINDOW_SECONDS.min;
147	    if (hasTimeInRange(times, start, end)) followedSpike += 1;
148	  }
149	
150	  return { wakeUps, followedSpike, baselineRate: randomWindowRate(times, input) };
151	}
