153	/**
154	 * Sums wake-up counts across nights. A percentage is included only once
155	 * `MIN_NIGHTS_FOR_PERCENTAGE` nights are pooled and there is at least one wake-up.
156	 * Fewer nights, or no wake-ups, stay as counts (docs/DOMAIN.md).
157	 */
158	export function pooledAttribution(
159	  nights: readonly { wakeUps: number; followedSpike: number }[],
160	): AttributionSummary {
161	  let wakeUps = 0;
162	  let followedSpike = 0;
163	  for (const night of nights) {
164	    wakeUps += night.wakeUps;
165	    followedSpike += night.followedSpike;
166	  }
167	  const nightsPooled = nights.length;
168	  if (nightsPooled >= MIN_NIGHTS_FOR_PERCENTAGE && wakeUps > 0) {
169	    return {
170	      display: "percentage",
171	      nightsPooled,
172	      wakeUps,
173	      followedSpike,
174	      percent: (followedSpike / wakeUps) * 100,
175	    };
176	  }
177	  return { display: "counts", nightsPooled, wakeUps, followedSpike };
178	}
179	
180	function sleepOnset(
181	  stages: readonly StageInterval[],
182	  sessionStart: number,
183	  sessionEnd: number,
184	): number | null {
185	  let onset: number | null = null;
186	  for (const stage of stages) {
187	    if (!ASLEEP.has(stage.stage)) continue;
188	    if (!Number.isFinite(stage.start) || !Number.isFinite(stage.end)) continue;
189	    if (stage.end <= stage.start) continue;
190	    if (stage.end <= sessionStart || stage.start >= sessionEnd) continue;
191	    const began = Math.max(stage.start, sessionStart);
192	    if (onset === null || began < onset) onset = began;
193	  }
194	  return onset;
195	}
196	
197	function asleepAt(stages: readonly StageInterval[], t: number): boolean {
198	  for (const stage of stages) {
199	    if (!ASLEEP.has(stage.stage)) continue;
200	    if (stage.start <= t && t < stage.end) return true;
201	  }
202	  return false;
203	}
204	
205	function heartSamples(
206	  samples: readonly (readonly [number, number])[] | undefined,
207	  sessionStart: number,
208	  sessionEnd: number,
209	): { t: number; bpm: number; index: number }[] {
210	  if (!samples) return [];
211	  const points: { t: number; bpm: number; index: number }[] = [];
212	  for (let i = 0; i < samples.length; i++) {
213	    const sample = samples[i];
214	    if (!sample) continue;
215	    const [t, bpm] = sample;
216	    if (!Number.isFinite(t) || !Number.isFinite(bpm)) continue;
217	    if (t < sessionStart || t >= sessionEnd) continue;
218	    points.push({ t, bpm, index: i });
219	  }
220	  points.sort((a, b) => a.t - b.t || a.index - b.index);
221	  return points;
222	}
223	
224	function sourceRank(source: WakeUp["source"]): number {
225	  return source === "stage" ? 0 : 1;
226	}
227	
228	function hasTimeInRange(times: readonly number[], start: number, end: number): boolean {
229	  if (!(end >= start)) return false;
230	  let lo = 0;
231	  let hi = times.length;
232	  while (lo < hi) {
233	    const mid = (lo + hi) >> 1;
234	    const value = times[mid];
235	    if (value !== undefined && value < start) lo = mid + 1;
236	    else hi = mid;
237	  }
238	  const found = times[lo];
239	  return found !== undefined && found <= end;
240	}
241	
242	function randomWindowRate(
243	  times: readonly number[],
244	  input: { nightStart: number; nightEnd: number; seed: number },
245	): number {
246	  if (times.length === 0) return 0;
247	  const length = ATTRIBUTION_WINDOW_SECONDS.max - ATTRIBUTION_WINDOW_SECONDS.min;
248	  const span = input.nightEnd - input.nightStart - length;
249	  if (!Number.isFinite(input.nightStart) || !Number.isFinite(span) || span < 0) return 0;
250	
251	  const rand = mulberry32(input.seed);
252	  let hits = 0;
253	  for (let i = 0; i < RANDOM_WINDOW_COUNT; i++) {
254	    const start = input.nightStart + (span === 0 ? 0 : rand() * span);
255	    if (hasTimeInRange(times, start, start + length)) hits += 1;
256	  }
257	  return hits / RANDOM_WINDOW_COUNT;
258	}
259	
260	/** Deterministic [0, 1) sequence. Same seed, same draws. */
261	function mulberry32(seed: number): () => number {
262	  let state = Number.isFinite(seed) ? seed | 0 : 0;
263	  return () => {
264	    state = (state + 0x6d2b79f5) | 0;
265	    let t = Math.imul(state ^ (state >>> 15), 1 | state);
266	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
267	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
268	  };
269	}
