  3	export type Scale = {
  4	  x: (epochSeconds: number) => number;
  5	  y: (db: number) => number;
  6	};
  7	
  8	export function makeScale(night: NightTimeline, width: number, height: number): Scale {
  9	  const start = Date.parse(night.startedAt) / 1000;
 10	  const end = Date.parse(night.endedAt) / 1000;
 11	  const values = [
 12	    night.baselineDb,
 13	    ...night.noise.map(([, db]) => db),
 14	    ...night.events.map((e) => e.peakDb),
 15	  ];
 16	  const span = end > start ? end - start : 1;
 17	  const lo = Math.min(...values) - 2;
 18	  const hi = Math.max(...values) + 2;
 19	  return {
 20	    x: (t) => ((Math.min(Math.max(t, start), end) - start) / span) * width,
 21	    y: (db) => height - ((db - lo) / (hi - lo)) * height,
 22	  };
 23	}
 24	
 25	export function clock(epochSeconds: number): string {
 26	  return new Date(epochSeconds * 1000).toLocaleTimeString("en-GB", {
 27	    hour: "2-digit",
 28	    minute: "2-digit",
 29	    timeZone: "Europe/London",
 30	  });
 31	}

