// Bundles entry.tsx for a plain browser page with react-native-web. Not committed.
import { dirname, join } from "node:path";

const here = import.meta.dir;
const root = dirname(dirname(here));
const rnw = Bun.resolveSync("react-native-web", root);

const result = await Bun.build({
  entrypoints: [join(here, "entry.tsx")],
  outdir: join(here, "out"),
  target: "browser",
  format: "iife",
  define: { "process.env.NODE_ENV": '"production"', __DEV__: "false" },
  plugins: [
    {
      name: "rn-web",
      setup(build) {
        build.onResolve({ filter: /^react-native$/ }, () => ({ path: rnw }));
        build.onResolve({ filter: /^@\// }, (args) => ({
          path: Bun.resolveSync(`./apps/mobile/src/${args.path.slice(2)}`, root),
        }));
      },
    },
  ],
});

if (!result.success) {
  for (const log of result.logs) console.error(log);
  process.exit(1);
}
console.log(result.outputs.map((o) => o.path).join("\n"));

